using System.Diagnostics;
using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Eval;

/// <summary>
/// Shared infrastructure for evaluation tests: chat client setup, telemetry, and reporting.
/// </summary>
internal static class EvalSetup
{
    private static readonly ActivitySource s_activitySource = new("MyApp.Eval");

    public static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? "test-key";

        var azureClient = new AzureOpenAIClient(new Uri(endpoint), new System.ClientModel.ApiKeyCredential(apiKey));
        IChatClient client = azureClient.GetChatClient("gpt-4o-mini").AsIChatClient();

        // Wrap with OpenTelemetry tracing for telemetry mode
        client = new ChatClientBuilder(client)
            .UseOpenTelemetry(sourceName: "MyApp.Eval")
            .Build();

        return client;
    }

    public static Activity? StartActivity(string name)
    {
        return s_activitySource.StartActivity(name);
    }

    public static IList<IEvaluationMetric> QualityMetrics(IChatClient judge)
    {
        return
        [
            new RelevanceMetric(judge),
            new CoherenceMetric(judge),
            new GroundednessMetric(judge),
            new FluencyMetric(judge),
        ];
    }

    public static ReportingConfiguration CreateReportingConfig(string storagePath)
    {
        return new ReportingConfiguration(storagePath);
    }
}

using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: validates that AI calls produce OpenTelemetry traces.
/// </summary>
[TestClass]
public class TelemetryTests
{
    [TestMethod]
    public async Task ChatCompletion_EmitsTrace()
    {
        using var activity = EvalSetup.StartActivity("TelemetryTest");
        var client = EvalSetup.CreateChatClient();

        var response = await client.GetResponseAsync("Hello, how are you?");

        Assert.IsNotNull(activity);
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
    }

    [TestMethod]
    public async Task StreamingCompletion_EmitsTrace()
    {
        using var activity = EvalSetup.StartActivity("TelemetryStreamTest");
        var client = EvalSetup.CreateChatClient();

        var chunks = new List<string>();
        await foreach (var update in client.GetStreamingResponseAsync("Say hello briefly."))
        {
            if (update.Text is not null)
                chunks.Add(update.Text);
        }

        Assert.IsNotNull(activity);
        Assert.IsTrue(chunks.Count > 0);
    }
}

using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: scores AI responses using relevance, coherence, groundedness, and fluency.
/// </summary>
[TestClass]
public class QualityTests
{
    private record QualityCase(string Input, string Context, string ExpectedTopic);

    private static IEnumerable<object[]> GetQualityCases()
    {
        var json = File.ReadAllText("Datasets/quality.json");
        var cases = JsonSerializer.Deserialize<List<QualityCase>>(json, new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true,
            PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        })!;

        foreach (var c in cases)
            yield return [c];
    }

    [TestMethod]
    [DynamicData(nameof(GetQualityCases), DynamicDataSourceType.Method)]
    public async Task Response_MeetsQualityThresholds(QualityCase testCase)
    {
        var client = EvalSetup.CreateChatClient();
        var judge = EvalSetup.CreateChatClient();

        var systemPrompt = $"You are a coaching assistant. Context: {testCase.Context}";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, systemPrompt),
            new(ChatRole.User, testCase.Input),
        };

        var response = await client.GetResponseAsync(messages);
        var responseText = response.Messages.Last().Text ?? string.Empty;

        var metrics = EvalSetup.QualityMetrics(judge);
        var context = new EvaluationContext
        {
            ModelResponse = responseText,
            GroundTruthContext = testCase.Context,
        };

        foreach (var metric in metrics)
        {
            await metric.EvaluateAsync(context);
        }

        // Assert all metrics pass a minimum threshold
        foreach (var metric in metrics)
        {
            var result = context.GetResult(metric);
            Assert.IsNotNull(result, $"Metric {metric.Name} produced no result");
            if (result is NumericMetricResult numeric)
            {
                Assert.IsTrue(numeric.Value >= 3.0,
                    $"Metric {metric.Name} scored {numeric.Value}, expected >= 3.0");
            }
        }
    }
}

using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Compare mode: runs baseline vs candidate prompts and compares metric scores.
/// </summary>
[TestClass]
public class CompareTests
{
    private record CompareCase(string Input, string Context);

    private const string BaselineSystemPrompt =
        "You are a helpful coaching assistant. Provide concise, actionable advice.";

    private const string CandidateSystemPrompt =
        "You are an expert leadership coach with deep experience in team dynamics. " +
        "Provide structured, empathetic advice with concrete next steps.";

    private static IEnumerable<object[]> GetCompareCases()
    {
        var json = File.ReadAllText("Datasets/compare.json");
        var cases = JsonSerializer.Deserialize<List<CompareCase>>(json, new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true,
            PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        })!;

        foreach (var c in cases)
            yield return [c];
    }

    [TestMethod]
    [DynamicData(nameof(GetCompareCases), DynamicDataSourceType.Method)]
    public async Task Candidate_ScoresAtLeastAsWellAsBaseline(CompareCase testCase)
    {
        var client = EvalSetup.CreateChatClient();
        var judge = EvalSetup.CreateChatClient();

        // Run baseline
        var baselineMessages = new List<ChatMessage>
        {
            new(ChatRole.System, BaselineSystemPrompt),
            new(ChatRole.User, testCase.Input),
        };
        var baselineResponse = await client.GetResponseAsync(baselineMessages);
        var baselineText = baselineResponse.Messages.Last().Text ?? string.Empty;

        // Run candidate
        var candidateMessages = new List<ChatMessage>
        {
            new(ChatRole.System, CandidateSystemPrompt),
            new(ChatRole.User, testCase.Input),
        };
        var candidateResponse = await client.GetResponseAsync(candidateMessages);
        var candidateText = candidateResponse.Messages.Last().Text ?? string.Empty;

        // Evaluate both
        var baselineMetrics = EvalSetup.QualityMetrics(judge);
        var candidateMetrics = EvalSetup.QualityMetrics(judge);

        var baselineContext = new EvaluationContext
        {
            ModelResponse = baselineText,
            GroundTruthContext = testCase.Context,
        };

        var candidateContext = new EvaluationContext
        {
            ModelResponse = candidateText,
            GroundTruthContext = testCase.Context,
        };

        foreach (var metric in baselineMetrics)
            await metric.EvaluateAsync(baselineContext);

        foreach (var metric in candidateMetrics)
            await metric.EvaluateAsync(candidateContext);

        // Compare: candidate should score >= baseline on relevance and coherence
        var baselineRelevance = baselineContext.GetResult(baselineMetrics[0]) as NumericMetricResult;
        var candidateRelevance = candidateContext.GetResult(candidateMetrics[0]) as NumericMetricResult;

        var baselineCoherence = baselineContext.GetResult(baselineMetrics[1]) as NumericMetricResult;
        var candidateCoherence = candidateContext.GetResult(candidateMetrics[1]) as NumericMetricResult;

        Assert.IsNotNull(baselineRelevance);
        Assert.IsNotNull(candidateRelevance);
        Assert.IsTrue(candidateRelevance.Value >= baselineRelevance.Value - 0.5,
            $"Candidate relevance ({candidateRelevance.Value}) regressed vs baseline ({baselineRelevance.Value})");

        Assert.IsNotNull(baselineCoherence);
        Assert.IsNotNull(candidateCoherence);
        Assert.IsTrue(candidateCoherence.Value >= baselineCoherence.Value - 0.5,
            $"Candidate coherence ({candidateCoherence.Value}) regressed vs baseline ({baselineCoherence.Value})");
    }
}

